Given n courses, labeled from 0 to n - 1 and an array prerequisites[] where prerequisites[i] = [x, y] indicates that we need to take course y first if we want to take course x. Find the ordering of courses we should take to complete all courses. If there are multiple solutions, return any of them. If it is impossible to finish all courses, return an empty array.Examples:Input: n = 3, prerequisites[][] = [[1, 0], [2, 1]]Output: [0, 1, 2]Explanation: To take course 1, you must finish course 0.To take course 2, you must finish course 1. So the only valid order is [0, 1, 2].Input: n = 4, prerequisites = [[2, 0], [2, 1], [3, 2]]Output: [1, 0, 2, 3]Explanation: Course 2 requires both 0 and 1.Course 3 requires course 2.Hence, both [0, 1, 2, 3] and [1, 0, 2, 3] are valid.Try It YourselfTable of Content[Approach 1]  Using Kahn's Algorithm[Approach 2]  Using DFS - O(m+n) Time and O(m+n) Space[Approach 1]  Using Kahn's AlgorithmWe  can solve this using Kahn’s Algorithm for Topological Sorting. We can think of each course as a node in a directed graph, and each prerequisite pair [a, b] as a directed edge from b → a.This means:To take course a, you must complete course b first.So, there is a directed edge from b (the prerequisite) to a (the dependent course).Once this graph is built, we have to find an ordering of courses such that every course appears after all its prerequisites this is exactly what topological sorting provides.
            C++

    #include <iostream>
#include <vector>
#include <queue>
using namespace std;

vector<int> findOrder(int n, vector<vector<int>>& prerequisites) {

    // Initialize graph and in-degree array
    vector<vector<int>> adj(n);
    vector<int> inDegree(n, 0);

    // Build the graph
    for (auto& pre : prerequisites) {
        int dest = pre[0];
        int src = pre[1];
        adj[src].push_back(dest);
        inDegree[dest]++;
    }

    // Initialize the queue with 
    // courses having in-degree 0
    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (inDegree[i] == 0) {
            q.push(i);
        }
    }

    vector<int> order;

    // Process nodes with BFS
    while (!q.empty()) {
        int current = q.front();
        q.pop();
        order.push_back(current);

        // Reduce in-degree for neighbors
        for (int neighbor : adj[current]) {
            inDegree[neighbor]--;
            if (inDegree[neighbor] == 0) {
                q.push(neighbor);
            }
        }
    }

    // Check if the topological sort 
    // is possible (i.e., no cycle)
    if (order.size() == n) {
        return order;
    } 

    return {}; 

}

int main() {
    int n = 4;
    vector<vector<int>> prerequisites = { {2, 0}, {2, 1}, {3, 2} };

    vector<int> order = findOrder(n, prerequisites);

    for (int course : order) {
        cout << course << " ";
    }
    cout << endl;

    return 0;
}


